setup.src/state.js:
// The editor's state: a title and a list of items, each item a list of tags.
function cloneState(s) {
  return { ...s, items: [...s.items] };
}
module.exports = { cloneState };

setup.src/store.js:
const { cloneState } = require('./state');
let current = { title: '', items: [] };
function commit(next) {
  current = cloneState(next);
  return current;
}
module.exports = { commit, get: () => current };

setup.src/undo.js:
const { cloneState } = require('./state');
const past = [];
function remember(s) {
  past.push(cloneState(s));
}
function undo() {
  return past.pop();
}
module.exports = { remember, undo };

setup.src/view.js:
function render(s) {
  return s.title + ': ' + s.items.map((tags) => tags.join(',')).join(' | ');
}
module.exports = { render };

